SourceCode.Declaration:
/// <summary>
/// The nightly posting of store journals (One journal per store): posts every store journal that
/// is not on hold, has no bin counted twice to decide, nobody still counting and something in it.
/// Schedule it to recur each night from Inventory hub > Counting > Post store journals.
/// </summary>
class HSMobileOpsCountStoreJournalPostBatch extends RunBaseBatch implements BatchRetryable
{
    #define.CurrentVersion(1)
}

Method.Source:
[Hookable(false)]
public final boolean isRetryable()
{
    return true;
}

public void run()
{
    int posted = HSMobileOpsCountStoreJournalEngine::postReady();

    info(strFmt('%1 store journal(s) posted.', posted));
}

public static ClassDescription description()
{
    return 'Mobile ops: post store journals';
}

public static void main(Args _args)
{
    HSMobileOpsCountStoreJournalPostBatch task = new HSMobileOpsCountStoreJournalPostBatch();

    if (task.prompt())
    {
        task.runOperation();
    }
}
